def quote(v):
    """One entry as a single-quoted YAML scalar (colons, apostrophes safe)."""
    return "'" + v.replace("'", "''") + "'"


def emit(block):
    out = []
    for line in block.splitlines():
        if not line.strip():
            continue
        key, val = line.split(': ', 1)
        out.append(key + ': ' + quote(val))
    return '\n'.join(out) + '\n'


for path, block in (('site/_data/summaries.yml', EN),
                    ('site/_data/summaries_de.yml', DE)):
    s = io.open(path, encoding='utf-8').read()
    lines = s.split('\n')
    if '--replace' in sys.argv:
        lines = [l for l in lines if not l.startswith(SLUG + '-')]
    elif any(l.startswith(SLUG + '-') for l in lines):
        sys.exit(path + ': entries already there (use --replace)')
    i = next(k for k, l in enumerate(lines) if l.startswith('ihagrrep7cnr3570-001:'))
    new = emit(block).rstrip('\n').split('\n')
    lines = lines[:i] + new + lines[i:]
    io.open(path, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines))
    print('wrote', path)
